from pathlib import Path
import json,hashlib,xml.etree.ElementTree as E
P=Path(__file__).resolve().parents[1];S=P/'source';U=P.parent;ROOT=U.parent;B=ROOT/'localization-integration-train-20261027/ci-successor';R=P/'independent-review'
j=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def normalize(data):
 if isinstance(data,dict):data=data['all_leaves']
 return{r['path']:(r['mode'],r['sha'])for r in data}
def verify(source,rows):
 for path,(mode,h)in rows.items():
  f=source/path;b=f.read_bytes();assert hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()==h,(source,path)
  assert('100755'if f.stat().st_mode&0o111 else'100644')==mode,(source,path)
 assert not [str(f.relative_to(source))for f in source.rglob('*')if f.is_file()and '__pycache__'not in f.parts and str(f.relative_to(source))not in rows]
def treehash(rows):
 root={}
 for p,(mode,h)in rows.items():
  node=root;parts=p.split('/')
  for part in parts[:-1]:node=node.setdefault(part,{})
  node[parts[-1]]=(mode,h)
 def rec(node):
  chunks=[]
  for name,v in sorted(node.items(),key=lambda kv:(kv[0]+('/'if isinstance(kv[1],dict)else'')).encode()):
   mode,h=('40000',rec(v))if isinstance(v,dict)else v
   chunks.append(mode.encode()+b' '+name.encode()+b'\0'+bytes.fromhex(h))
  b=b''.join(chunks);return hashlib.sha1(b'tree '+str(len(b)).encode()+b'\0'+b).hexdigest()
 return rec(root)

now=normalize(j(P/'expected-source-tree.json'));base=normalize(j(B/'expected-source-tree.json'));verify(S,now);verify(B/'source',base)
assert treehash(now)==j(P/'expected-source-tree.json')['expected_tree'];assert treehash(base)==j(P/'expected-source-tree.json')['base_tree']
changed={p for p in set(base)|set(now) if base.get(p)!=now.get(p)};assert changed=={r['path'] for r in j(P/'expected-source-tree.json')['tree_elements']} and len(changed)==17
historical=[p for p in base if '/fixtures/' in p or '/src/test/resources/' in p];assert all(now[p]==base[p] for p in historical)

fixturepath='tools/fixtures/current_localization/croatian_bosnian_serbian_priority_wording.json';assert (S/fixturepath).read_bytes()==(U/'source-composite'/fixturepath).read_bytes()
f=j(S/fixturepath);maps=j(U/'accepted-edit-maps.json')['locales'];bindings={}
for tag,folder in {'hr':'values-hr','bs':'values-bs','sr-Cyrl':'values-b+sr+Cyrl','sr-Latn':'values-b+sr+Latn'}.items():
 vals=f['locales'][tag]['values'];m={r['identity'].split('/')[1]:r for r in maps[tag]};assert set(vals)==set(m)
 for k,v in vals.items():assert v['target']==m[k]['target'] and v['attributes']==m[k]['attributes'],(tag,k)
 path='Paintroid/src/main/res/'+folder+'/strings.xml';assert (S/path).read_bytes()==(U/'source-composite'/path).read_bytes();bindings[tag]={'edits':len(vals),'holds':len(f['locales'][tag]['holds'])}
assert sum(x['edits']for x in bindings.values())==638
assert not any('/src/main/java/' in p or 'AppLanguage' in p or '/androidTest/' in p or p.startswith('.github/') for p in changed)
result={'tree':treehash(now),'manifest_sha256':sha(P/'expected-source-tree.json'),'leaves':len(now),'changed_paths':sorted(changed),'historical_files_unchanged':len(historical),'original_maps_sha256':sha(U/'accepted-edit-maps.json'),'original_complete_review_sha256':sha(U/'full-reconciled-reviewed.json'),'catalogue_bindings':bindings,'original_fixture_sha256':sha(S/fixturepath),'fresh_linguistic_credit':0}
(R/'binding-review.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))

