from pathlib import Path
import re,json,hashlib,difflib
P=Path(__file__).resolve().parents[1];U=P.parent;B=U.parent/'localization-integration-train-20261027/ci-successor/source';S=P/'source';R=P/'independent-review';prefix='Paintroid/src/test/java/org/catrobat/paintroid/local/'
def methods(s):
 out={}
 for m in re.finditer(r'    @Test\s+fun (\w+)\(',s):
  end=re.search(r'^    }\s*$',s[m.end():],re.M);assert end
  out[m[1]]=s[m.start():m.end()+end.end()].rstrip()
 return out
report={}
for name in ['CroatianBosnianP0WordingTest','SerbianP0WordingTest','CroatianBosnianSerbianPriorityWordingTest']:
 path=prefix+name+'.kt';old=(U/'source-composite')/path;a=old.read_text();b=(S/path).read_text();am=methods(a);bm=methods(b);allowed=set()
 assert set(am)<=set(bm);assert all(am[k]==bm[k]for k in set(am)-allowed)
 report[name]={'prior_methods':len(am),'result_methods':len(bm),'exact_prior_method_bodies':sorted(set(am)-allowed),'finite_existing_method_changes':sorted(allowed)}
 (R/(name+'.diff')).write_text(''.join(difflib.unified_diff(a.splitlines(True),b.splitlines(True))))
(R/'jvm-preservation.json').write_text(json.dumps(report,indent=2)+'\n');print({k:(v['prior_methods'],v['result_methods'])for k,v in report.items()})
